const personal = ['gmail.com','googlemail.com','yahoo.com','hotmail.com','outlook.com','live.com','msn.com','aol.com','icloud.com','me.com','mac.com','proton.me','protonmail.com','gmx.com','mail.com','yandex.com','zoho.com','att.net','comcast.net','bellsouth.net','charter.net','sbcglobal.net','verizon.net','cox.net'];
const domain = String($json.domain || '').toLowerCase().trim();
const isPersonal = personal.includes(domain);
return { json: { ...$json, domain, personal_email: isPersonal, site_url: (!domain || isPersonal) ? '' : 'https://' + domain, fail_reason: !domain ? 'no email domain' : (isPersonal ? 'personal email address, no company site to read' : '') } };

const r = $json;
if (r.error) {
  const msg = String(r.error.message || r.error.description || r.error || 'request failed');
  return { json: { page_text: '', fail_reason: 'site unreachable: ' + msg.slice(0, 120) } };
}
const decode = s => s
  .replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(Number(d)))
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&rsquo;|&lsquo;/g, "'").replace(/&rdquo;|&ldquo;|&quot;/g, '"').replace(/&mdash;/g, '-').replace(/&ndash;/g, '-');
const html = String(r.html ?? r.data ?? '');
const title = decode((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
const desc = decode((html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i) || [])[1] || '');
const text = decode(html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/\s+/g, ' ').trim();
if (text.length < 200) return { json: { page_text: '', fail_reason: 'site has too little readable text' } };
return { json: { page_text: [title, desc, text].filter(Boolean).join('\n').slice(0, 8000), fail_reason: '' } };

if ($json.error) return { json: { enriched: false, fail_reason: 'Claude call failed' } };
const c = $json.content;
let raw = typeof c === 'string' ? c : Array.isArray(c) ? c.map(p => p.text ?? '').join('') : ($json.text ?? '');
let p;
try { p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); }
catch (err) { return { json: { enriched: false, fail_reason: 'could not parse Claude output' } }; }
const sizes = ['1_10', '11_50', '51_200', '200_plus', 'unknown'];
return { json: {
  enriched: true,
  fail_reason: '',
  what_they_do: String(p.what_they_do || ''),
  size_hint: sizes.includes(p.size_hint) ? p.size_hint : 'unknown',
  location: String(p.location || ''),
  services: Array.isArray(p.services) ? p.services.slice(0, 6).map(String) : [],
  summary: String(p.summary || '').slice(0, 400)
} };

// Lead scoring. Same rules as 01-lead-intake/enrich/enrich.py (score_lead).
const lead = $json.lead || {};
const enriched = !!$json.enriched;
const failReason = $json.fail_reason || lead.fail_reason || 'enrichment unavailable';
const sizeHint = enriched ? $json.size_hint : 'unknown';
const sizePts = { '1_10': 10, '11_50': 25, '51_200': 30, '200_plus': 20 };
const sizeLabel = { '1_10': '1-10', '11_50': '11-50', '51_200': '51-200', '200_plus': '200+', 'unknown': 'unknown' };
const message = String(lead.message || '');
let score = 20;
const why = ['20 base'];
if (enriched) {
  score += 20; why.push('+20 company site read');
  if (sizePts[sizeHint]) { score += sizePts[sizeHint]; why.push(`+${sizePts[sizeHint]} size ${sizeLabel[sizeHint]}`); }
}
if (lead.phone) { score += 10; why.push('+10 phone given'); }
if (lead.company) { score += 5; why.push('+5 company named'); }
if (message.length > 60) { score += 10; why.push('+10 detailed request'); }
if (/\b(today|tomorrow|asap|urgent|emergency|this week|right away)\b/i.test(message)) { score += 10; why.push('+10 urgency'); }
if (lead.personal_email) { score -= 10; why.push('-10 personal email'); }
score = Math.max(0, Math.min(100, score));
const name = lead.name || lead.email || 'lead';
const label = String(lead.source_label || '');
const retryNote = label.startsWith('Retry') ? ` (${label})` : '';
const reasons = why.join(', ');
const services = $json.services || [];
const location = $json.location || '';
const slack_text = enriched
  ? `:mag: *Enrichment*${retryNote} for ${name}\n${$json.summary || ''}\n*Does:* ${$json.what_they_do || 'n/a'} · *Size:* ${sizeLabel[sizeHint] || 'unknown'} · *Location:* ${location || 'n/a'}${services.length ? '\n*Services:* ' + services.join(', ') : ''}\n*Lead score:* ${score}/100 (${reasons})`
  : `:warning: *Enrichment failed*${retryNote} for ${name}: ${failReason}. Scored from the form fields only.\n*Lead score:* ${score}/100 (${reasons})`;
return { json: {
  email: lead.email || '',
  slack_ts: lead.slack_ts || '',
  lead_score: score,
  score_reasons: reasons,
  enrichment_status: enriched ? 'done' : 'failed',
  company_summary: enriched ? `${$json.summary || ''}${location ? ' (' + location + ')' : ''}` : '',
  company_size_hint: enriched ? sizeHint : 'unknown',
  fail_reason: enriched ? '' : failReason,
  slack_text
} };
